package com.nexushr.service; import com.nexushr.dto.AuthDtos.*; import com.nexushr.entity.*; import com.nexushr.repository.UserRepository; import com.nexushr.security.JwtService; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class AuthService { private final UserRepository users; private final PasswordEncoder encoder; private final JwtService jwt; public AuthService(UserRepository u,PasswordEncoder e,JwtService j){users=u;encoder=e;jwt=j;} public AuthResponse login(LoginRequest r){var u=users.findByEmailIgnoreCase(r.email()).orElseThrow(()->new IllegalArgumentException("Invalid credentials")); if(!u.isActive()||!encoder.matches(r.password(),u.getPasswordHash()))throw new IllegalArgumentException("Invalid credentials"); return new AuthResponse(jwt.generate(u.getEmail(),u.getRole().name()),u.getEmail(),u.getRole().name());} @Transactional public User register(RegisterRequest r){if(users.findByEmailIgnoreCase(r.email()).isPresent())throw new IllegalArgumentException("Email already exists"); var u=new User();u.setEmail(r.email().toLowerCase());u.setPasswordHash(encoder.encode(r.password()));u.setRole(Role.valueOf(r.role()==null?"EMPLOYEE":r.role().toUpperCase()));return users.save(u);} }
